import{_ as t,c as a,o as i,a3 as n}from"./chunks/framework.MI-M1z4O.js";const p=JSON.parse(`{"title":"Scrumban Stage-by-Stage Activities","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","frontmatter":{"title":"Scrumban Stage-by-Stage Activities","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban introduction, Scrumban concept, what is Scrumban, Scrum vs Kanban, agile methodology, agile framework, Kanban methodology, Scrum methodology, Scrumban process, Scrumban operations guide, Scrumban board, WIP limit, workflow management, how to use Kanban board, Scrumban benefits, Scrumban characteristics, Scrumban impact, Scrumban use cases, Scrumban adoption benefits, Scrumban Jira setup, Scrumban board template, Scrumban tool, Scrumban collaboration tool, Scrumban workflow, agile project management, work efficiency methodology, iterative task management, bottleneck resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/activity"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/activity"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/activity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/activity"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/activity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/activity"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Scrumban Stage-by-Stage Activities | Empasy Docs"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/activity"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Scrumban Stage-by-Stage Activities | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}]],"sort":400},"headers":[],"relativePath":"en/agile/activity.md","filePath":"en/agile/activity.md","lastUpdated":1795293539000}`),r={name:"en/agile/activity.md"};function s(o,e,l,d,c,g){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="scrumban-stage-by-stage-activity-guide" tabindex="-1">Scrumban Stage-by-Stage Activity Guide <a class="header-anchor" href="#scrumban-stage-by-stage-activity-guide" aria-label="Permalink to “Scrumban Stage-by-Stage Activity Guide”">​</a></h1><table tabindex="0"><thead><tr><th>Stage</th><th>Key Activities</th><th>Detailed Description</th></tr></thead><tbody><tr><td><strong>1. Backlog</strong></td><td>- Collect new ideas/requests<br>- Record backlog items<br>- Assign Class of Service</td><td>The starting point for all work.<br>The <strong>Product Owner</strong> or team records business requests, bugs, technical debt, and similar items.<br>Each card is assigned a <strong>priority</strong> and a <strong>work type (Expedite, Fixed Date, Standard, Intangible)</strong>.<br>Items at this stage are not yet ready to start.</td></tr><tr><td><strong>2. Ready</strong></td><td>- Verify Definition of Ready (DoR)<br>- Break down tasks (if needed)<br>- Unassigned</td><td>Tasks refined to the point where work can begin immediately.<br>Must satisfy DoR criteria (clear requirements, design/resources secured, test conditions defined, etc.).<br>Typically moved from Backlog to Ready during a <strong>Replenishment meeting</strong>.</td></tr><tr><td><strong>3. Doing / In Progress</strong></td><td>- Pull work to start<br>- Update in-progress status<br>- Flag blockers</td><td>Team members pull tasks from Ready within the WIP limit to begin work.<br>Any <strong>bottlenecks or blockers</strong> encountered during execution are visually flagged on the board (red labels, icons, etc.).<br>Status is shared during the Daily Stand-up.</td></tr><tr><td><strong>4. Review (Code Review / Peer Review)</strong></td><td>- Perform code/document review<br>- Incorporate feedback</td><td>Completed development work moves to the Review column.<br>Designated reviewers verify code quality and adherence to standards.<br>If review feedback requires changes, the item moves back to Doing or is updated and re-reviewed.</td></tr><tr><td><strong>5. Testing / QA</strong></td><td>- Run functional tests<br>- File bug reports and fix defects</td><td>QA or team members execute tests.<br>Automated and manual testing can be run in parallel.<br>If defects are found, they are logged on the card, fixed, and re-verified.</td></tr><tr><td><strong>6. Done</strong></td><td>- Verify Definition of Done (DoD) compliance<br>- Update documentation/release notes<br>- Complete deployment</td><td>All quality criteria are met and deployment is complete.<br>Includes documentation updates such as release notes and user manuals.<br>The completion date is recorded on the card for cycle time analysis.</td></tr></tbody></table><hr><h2 id="stage-by-stage-activity-flow-visualization" tabindex="-1">Stage-by-Stage Activity Flow Visualization <a class="header-anchor" href="#stage-by-stage-activity-flow-visualization" aria-label="Permalink to “Stage-by-Stage Activity Flow Visualization”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishment Meeting)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIP Check)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (Development Complete)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (Review Approved)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (Quality Verification Complete)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="stage-by-stage-operational-tips" tabindex="-1">Stage-by-Stage Operational Tips <a class="header-anchor" href="#stage-by-stage-operational-tips" aria-label="Permalink to “Stage-by-Stage Operational Tips”">​</a></h2><h3 id="_1-backlog" tabindex="-1">1. Backlog <a class="header-anchor" href="#_1-backlog" aria-label="Permalink to “1. Backlog”">​</a></h3><ul><li><strong>Clarify prioritization criteria</strong>: Base decisions on urgency, business value, deadlines, and risk.</li><li><strong>Standardize card size</strong>: Split overly large items before moving them to Ready.</li><li><strong>Prune regularly</strong>: Discard outdated or unnecessary cards.</li></ul><h3 id="_2-ready" tabindex="-1">2. Ready <a class="header-anchor" href="#_2-ready" aria-label="Permalink to “2. Ready”">​</a></h3><ul><li><p><strong>Example Definition of Ready (DoR) Checklist</strong></p><ul><li>Requirements are clear</li><li>Design, data, and resources are secured</li><li>Test conditions are defined</li><li>Estimated effort and scope are confirmed</li></ul></li></ul><h3 id="_3-doing" tabindex="-1">3. Doing <a class="header-anchor" href="#_3-doing" aria-label="Permalink to “3. Doing”">​</a></h3><ul><li>Follow the <strong>Stop Starting, Start Finishing</strong> rule.</li><li>Discuss and resolve bottlenecks immediately when they occur.</li><li>Minimize multitasking.</li></ul><h3 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to “4. Review”">​</a></h3><ul><li>Define code review criteria (e.g., code style, performance, security, test coverage).</li><li>Leverage notification systems to reduce review wait times.</li></ul><h3 id="_5-testing" tabindex="-1">5. Testing <a class="header-anchor" href="#_5-testing" aria-label="Permalink to “5. Testing”">​</a></h3><ul><li>Combine automated testing with manual testing.</li><li>When bugs occur, fix and re-verify them on the same card.</li><li>Allow temporary WIP limit exceptions when tests fail, if necessary.</li></ul><h3 id="_6-done" tabindex="-1">6. Done <a class="header-anchor" href="#_6-done" aria-label="Permalink to “6. Done”">​</a></h3><ul><li>Record <strong>cycle time</strong> on the card upon completion.</li><li>Review completed cards during release retrospectives.</li><li>Apply tags (e.g., bug, new feature) for data analysis.</li></ul><hr><h2 id="key-metrics-by-stage" tabindex="-1">Key Metrics by Stage <a class="header-anchor" href="#key-metrics-by-stage" aria-label="Permalink to “Key Metrics by Stage”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Key Metrics</th><th>Purpose</th></tr></thead><tbody><tr><td>Backlog → Ready</td><td>Lead time (request to ready)</td><td>Identify causes of preparation delays</td></tr><tr><td>Ready → Doing</td><td>Pull frequency</td><td>Assess team throughput capacity</td></tr><tr><td>Doing</td><td>Average WIP, blocker ratio</td><td>Manage bottlenecks</td></tr><tr><td>Review</td><td>Review wait time</td><td>Balance quality and delivery speed</td></tr><tr><td>Testing</td><td>Defect rate, rework rate</td><td>Measure QA efficiency</td></tr><tr><td>Done</td><td>Cycle time, throughput</td><td>Improve predictability</td></tr></tbody></table><hr><p>Organizing workflows this way clarifies <strong>what a team adopting Scrumban needs to do at each stage</strong>, while also enabling <strong>metric-driven continuous improvement</strong>.</p><hr>`,25)])])}const h=t(r,[["render",s]]);export{p as __pageData,h as default};
